from openai import AzureOpenAI
import os

def get_azure_openai_client(config):
    return AzureOpenAI(
        azure_endpoint=config.get("endpoint", os.environ.get("AZURE_OPENAI_ENDPOINT")),
        api_key=config.get("api_key", os.environ.get("AZURE_OPENAI_API_KEY")),
        api_version=config.get("api_version", "2024-10-21")
    )

def get_azure_openai_deployment(config):
    return config.get("deployment", os.environ.get("AZURE_OPENAI_DEPLOYMENT_NAME"))

import dataclasses

@dataclasses.dataclass
class PlatformModelRequest:
    text: str

@dataclasses.dataclass
class PlatformModelResponse:
    text: str
    metadata: dict = dataclasses.field(default_factory=dict)

from model_client import get_azure_openai_deployment

def select_platform_resource(config=None):
    config = config or {}
    # In a real scenario, this function might contain logic to select
    # the appropriate deployment based on various criteria (e.g., model capabilities, cost, region).
    # For this example, we directly use the configured deployment.
    deployment_name = get_azure_openai_deployment(config)
    if not deployment_name:
        raise ValueError("Azure OpenAI deployment name not found in config or environment variables.")
    return {"deployment_name": deployment_name}

from model_client import get_azure_openai_client, get_azure_openai_deployment
from model_models import PlatformModelRequest, PlatformModelResponse

def collect_platform_metadata(payload: PlatformModelRequest, config=None):
    config = config or {}
    client = get_azure_openai_client(config)
    deployment_name = get_azure_openai_deployment(config)

    messages = [{'role': 'user', 'content': payload.text}]

    response = client.chat.completions.create(
        model=deployment_name,
        messages=messages
    )

    text_output = response.choices[0].message.content or ''
    metadata = {
        "id": response.id,
        "model": response.model,
        "created": response.created,
        "usage": response.usage.model_dump() if response.usage else None
    }
    return PlatformModelResponse(text=text_output, metadata=metadata)

from azure.ai.contentsafety import ContentSafetyClient
from azure.core.credentials import AzureKeyCredential
from azure.ai.contentsafety.models import AnalyzeTextOptions, TextCategory
import os

def check_platform_output_safety(text_output, config=None):
    config = config or {}
    endpoint = config.get("azure_content_safety_endpoint", os.environ.get("AZURE_CONTENT_SAFETY_ENDPOINT"))
    key = config.get("azure_content_safety_key", os.environ.get("AZURE_CONTENT_SAFETY_KEY"))

    if not endpoint or not key:
        print("Azure Content Safety endpoint or key not configured. Skipping safety check.")
        return {"is_safe": True, "analysis_results": []}

    client = ContentSafetyClient(endpoint, AzureKeyCredential(key))

    # Categories to check. Adjust as needed.
    categories = [
        TextCategory.HATE,
        TextCategory.VIOLENCE,
        TextCategory.SEXUAL,
        TextCategory.SELF_HARM,
    ]

    request = AnalyzeTextOptions(text=text_output, categories=categories)
    response = client.analyze_text(request)

    analysis_results = []
    is_safe = True
    for category in response.categories_analysis:
        analysis_results.append({
            "category": category.category.value,
            "severity": category.severity
        })
        # Assuming severity 2 or higher indicates potential unsafety
        if category.severity and category.severity >= 2:
            is_safe = False

    return {"is_safe": is_safe, "analysis_results": analysis_results}

import os
import requests
import uuid

def translate_platform_output(text_output, target_locale, config=None):
    config = config or {}
    key = config.get("azure_translator_key", os.environ.get("AZURE_TRANSLATOR_KEY"))
    endpoint = config.get("azure_translator_endpoint", os.environ.get("AZURE_TRANSLATOR_ENDPOINT"))
    location = config.get("azure_translator_location", os.environ.get("AZURE_TRANSLATOR_LOCATION"))

    if not key or not endpoint or not location:
        print("Azure Translator key, endpoint, or location not configured. Skipping translation.")
        return {"translated_text": text_output, "source_locale": "en", "target_locale": target_locale}

    path = '/translate'
    constructed_url = endpoint + path

    headers = {
        'Ocp-Apim-Subscription-Key': key,
        'Ocp-Apim-Subscription-Region': location,
        'Content-type': 'application/json',
        'X-ClientTraceId': str(uuid.uuid4())
    }

    body = [{
        'text': text_output
    }]

    params = {
        'api-version': '3.0',
        'to': target_locale
    }

    request = requests.post(constructed_url, params=params, headers=headers, json=body)
    response = request.json()

    if response and isinstance(response, list) and 'translations' in response[0]:
        translated_text = response[0]['translations'][0]['text']
        source_locale = response[0]['detectedLanguage']['language']
        return {"translated_text": translated_text, "source_locale": source_locale, "target_locale": target_locale}
    else:
        print(f"Translation failed: {response}")
        return {"translated_text": text_output, "source_locale": "en", "target_locale": target_locale}

